109	pub fn read_lexicon(residual_dir: &Path) -> Result<Vec<Term>> {
110	    let path = residual_dir.join("lexicon.csv");
111	    if !path.exists() {
112	        return Ok(vec![]);
113	    }
114	    let mut rdr = csv::ReaderBuilder::new()
115	        .has_headers(true)
116	        .from_path(&path)?;
117	    let mut out = Vec::new();
118	    for rec in rdr.deserialize() {
119	        out.push(rec?);
120	    }
121	    Ok(out)
122	}
123	
124	fn parse_residue_cell(cell: &str) -> (String, String) {
125	    if let Some((status, notes)) = cell.split_once('|') {
126	        (status.trim().to_string(), notes.trim().to_string())
127	    } else {
128	        (cell.trim().to_string(), String::new())
129	    }
130	}
131	
132	fn format_residue_cell(status: &str, notes: &str) -> String {
133	    if notes.is_empty() {
134	        status.to_string()
135	    } else {
136	        format!("{status}|{notes}")
137	    }
138	}
139	
140	fn residues_is_matrix_header(header: &str) -> bool {
141	    header
142	        .split(',')
143	        .next()
144	        .map(|c| c.trim().eq_ignore_ascii_case(RESIDUES_MATRIX_FORCE_COL))
145	        .unwrap_or(false)
146	}
147	
148	fn residues_to_rows(
149	    residues: &[Residue],
150	) -> (
151	    Vec<String>,
152	    BTreeMap<String, BTreeMap<String, (String, String)>>,
153	) {
154	    let mut components = BTreeSet::new();
155	    let mut cells: BTreeMap<String, BTreeMap<String, (String, String)>> = BTreeMap::new();
156	    for r in residues {
157	        if r.force_id.is_empty() || r.component_id.is_empty() {
158	            continue;
159	        }
160	        components.insert(r.component_id.clone());
161	        cells
162	            .entry(r.force_id.clone())
163	            .or_default()
164	            .insert(r.component_id.clone(), (r.status.clone(), r.notes.clone()));
165	    }
166	    (components.into_iter().collect(), cells)
167	}
168	
169	fn render_residues_matrix(residues: &[Residue]) -> String {
170	    let (components, cells) = residues_to_rows(residues);
171	    let mut buf = RESIDUES_MATRIX_FORCE_COL.to_string();
172	    for c in &components {
173	        buf.push(',');
174	        buf.push_str(c);
175	    }
176	    buf.push('\n');
177	    for force_id in cells.keys() {
178	        let force_cells = cells
179	            .get(force_id)
180	            .expect("force_id comes from cells.keys()");
181	        let mut row = vec![force_id.as_str()];
182	        let mut cell_values = Vec::new();
183	        for c in &components {
184	            cell_values.push(
185	                force_cells
186	                    .get(c)
187	                    .map(|(s, n)| format_residue_cell(s, n))
188	                    .unwrap_or_default(),
189	            );
190	        }
191	        for v in &cell_values {
192	            row.push(v.as_str());
193	        }
194	        let mut out = Vec::new();
195	        {
196	            let mut wtr = csv::WriterBuilder::new()
197	                .has_headers(false)
198	                .from_writer(&mut out);
199	            wtr.write_record(&row)
200	                .expect("csv write to Vec<u8> is infallible");
201	            wtr.flush().expect("csv flush to Vec<u8> is infallible");
202	        }
203	        buf.push_str(
204	            std::str::from_utf8(&out).expect("csv output is always valid UTF-8"),
205	        );
206	    }
207	    buf
208	}
209	
210	pub fn format_residues_matrix(residual_dir: &Path) -> Result<String> {
211	    Ok(render_residues_matrix(&read_residues(residual_dir)?))
212	}
213	
214	pub fn write_residues(residual_dir: &Path, residues: &[Residue]) -> Result<()> {
215	    std::fs::write(
216	        residual_dir.join("residues.csv"),
217	        render_residues_matrix(residues),
218	    )?;
219	    Ok(())
220	}
221	
222	pub fn read_residues(residual_dir: &Path) -> Result<Vec<Residue>> {
223	    let path = residual_dir.join("residues.csv");
224	    if !path.exists() {
225	        return Ok(vec![]);
226	    }
227	    let text = std::fs::read_to_string(&path)?;
228	    let mut lines = text.lines();
229	    let header = lines.next().unwrap_or("");
230	    if header.trim().is_empty() {
231	        return Ok(vec![]);
232	    }
233	    if residues_is_matrix_header(header) {
234	        return read_residues_matrix(header, lines);
235	    }
236	    read_residues_legacy(&path)
237	}
238	
239	fn read_residues_matrix<'a, I>(header: &str, rows: I) -> Result<Vec<Residue>>
240	where
241	    I: Iterator<Item = &'a str>,
242	{
243	    let components: Vec<String> = header
244	        .split(',')
245	        .skip(1)
246	        .map(|s| s.trim().to_string())
247	        .filter(|s| !s.is_empty())
248	        .collect();
249	    let mut out = Vec::new();
250	    let mut id_n = 0u32;
251	    for line in rows {
252	        if line.trim().is_empty() {
253	            continue;
254	        }
255	        let mut rdr = csv::ReaderBuilder::new()
256	            .has_headers(false)
257	            .from_reader(line.as_bytes());
258	        let rec = rdr.records().next().transpose()?.unwrap_or_default();
259	        let force_id = rec.get(0).unwrap_or("").trim().to_string();
260	        if force_id.is_empty() {
261	            continue;
262	        }
263	        for (i, component_id) in components.iter().enumerate() {
264	            let cell = rec.get(i + 1).unwrap_or("").trim();
265	            if cell.is_empty() {
266	                continue;
267	            }
268	            id_n += 1;
269	            let (status, notes) = parse_residue_cell(cell);
270	            out.push(Residue {
271	                id: format!("R-{id_n:02}"),
272	                force_id: force_id.clone(),
273	                component_id: component_id.clone(),
274	                status,
275	                notes,
276	            });
277	        }
278	    }
279	    Ok(out)
280	}
281	
282	fn read_residues_legacy(path: &Path) -> Result<Vec<Residue>> {
