290	            id: rec.get(0).unwrap_or("").to_string(),
291	            force_id: rec.get(1).unwrap_or("").to_string(),
292	            component_id: rec.get(2).unwrap_or("").to_string(),
293	            status: rec.get(3).unwrap_or("").to_string(),
294	            notes: rec.get(4).unwrap_or("").to_string(),
295	        });
296	    }
297	    Ok(out)
298	}
