30	    let dir = &cfg.residual_dir;
31	    fs::create_dir_all(dir.join("iterations"))?;
32	    fs::create_dir_all(dir.join("personas"))?;
33	    fs::create_dir_all(dir.join("research"))?;
34	
35	    // Write v3 config.toml if not present (storage-config owns app + verify policy).
36	    let config_path = dir.join("config.toml");
37	    if !config_path.exists() {
38	        let toml = crate::storage::config::render_v3(&crate::storage::config::StorageConfig::default());
39	        fs::write(&config_path, toml)?;
40	    }
41	
42	    // Write empty CSVs with headers if not present
43	    let csvs: &[(&str, &str)] = &[
44	        ("stressors.csv", "id,shortname,description,naive_change,outcomes,components_affected,attractor_id"),
45	        ("purposes.csv", "id,shortname,description,feature,outcomes,components_enabled,attractor_id"),
46	        ("attractors.csv", "id,name,description,positive_state,negative_state"),
47	        ("terminology.csv", "term,definition,domain,related_terms"),
48	        ("forces.csv", "id,kind,shortname,naive_change,outcomes,description,attractor_id"),
49	        ("lexicon.csv", "term,definition,domain,aliases"),
50	        ("residues.csv", "force"),
51	        ("components.csv", "name,description,status,architecture_set"),
52	    ];
