69	fn add_entry(cfg: &Config, target: AddTarget) -> Result<()> {
70	    let dir = &cfg.residual_dir;
71	    match target {
72	        AddTarget::Stressor {
73	            description,
74	            attractor_id,
75	            naive_change,
76	            shortname,
77	            outcomes,
78	            components,
79	            whole_system,
80	            notes,
81	        } => {
