29	pub fn append(residual_dir: &Path, term: Term) -> Result<()> {
30	    let path = residual_dir.join("terminology.csv");
31	    let file_exists = path.exists() && std::fs::metadata(&path).map(|m| m.len() > 0).unwrap_or(false);
32	    use std::io::Write;
33	    let mut file = std::fs::OpenOptions::new()
34	        .create(true)
35	        .append(true)
36	        .open(&path)?;
37	    if !file_exists {
38	        writeln!(file, "term,definition,domain,related_terms")?;
39	    }
40	    let mut buf = Vec::new();
41	    {
42	        let mut wtr = csv::WriterBuilder::new()
43	            .has_headers(false)
44	            .from_writer(&mut buf);
45	        wtr.write_record(&[
46	            &term.term,
47	            &term.definition,
48	            &term.domain,
49	            &term.related_terms,
50	        ])?;
51	        wtr.flush()?;
52	    }
53	    file.write_all(&buf)?;
54	    Ok(())
55	}
