61	#[derive(Debug, Clone)]
62	pub struct TermIndex {
63	    pub words: std::collections::HashSet<String>,
64	    pub phrases: Vec<String>,
65	}
66	
67	fn add_index_tokens(
68	    words: &mut std::collections::HashSet<String>,
69	    phrases: &mut Vec<String>,
70	    raw: &str,
71	) {
72	    let trimmed = raw.trim().to_lowercase();
73	    if trimmed.is_empty() {
74	        return;
75	    }
76	    phrases.push(trimmed.clone());
77	    words.insert(trimmed.clone());
78	    for token in trimmed.split_whitespace() {
79	        if !token.is_empty() {
80	            words.insert(token.to_string());
81	        }
82	    }
83	}
84	
85	pub fn term_index(residual_dir: &Path) -> Result<TermIndex> {
86	    let mut words = std::collections::HashSet::new();
87	    let mut phrases = Vec::new();
88	
89	    for t in load(residual_dir)? {
90	        add_index_tokens(&mut words, &mut phrases, &t.term);
91	        for alias in t.related_terms.split('|') {
92	            add_index_tokens(&mut words, &mut phrases, alias);
93	        }
94	    }
95	
96	    for t in crate::storage::format::read_lexicon(residual_dir)? {
97	        add_index_tokens(&mut words, &mut phrases, &t.term);
98	        for alias in t.aliases.split('|') {
99	            add_index_tokens(&mut words, &mut phrases, alias);
100	        }
101	    }
102	
103	    phrases.sort_by_key(|p| std::cmp::Reverse(p.len()));
104	    phrases.dedup();
105	
106	    Ok(TermIndex { words, phrases })
107	}
