145	pub fn check_links(cfg: &Config) -> Result<Vec<LinkViolation>> {
146	    let stressors = crate::storage::stressors::load(&cfg.residual_dir)?;
147	    let purposes = crate::storage::purposes::load(&cfg.residual_dir)?;
148	    let attractors = crate::storage::attractors::load(&cfg.residual_dir)?;
149	    let attractor_ids: std::collections::HashSet<String> =
150	        attractors.iter().map(|a| a.id.clone()).collect();
151	
152	    let mut violations = Vec::new();
153	
154	    for stressor in &stressors {
155	        if !stressor.attractor_id.is_empty() && !attractor_ids.contains(&stressor.attractor_id) {
156	            violations.push(LinkViolation {
157	                source: "stressor".to_string(),
158	                id: stressor.id.clone(),
159	                message: format!("missing attractor '{}'", stressor.attractor_id),
160	            });
161	        }
162	        if stressor.shortname.is_empty() {
163	            violations.push(LinkViolation {
164	                source: "stressor".to_string(),
165	                id: stressor.id.clone(),
166	                message: "missing shortname (use --shortname when adding)".to_string(),
167	            });
168	        }
169	    }
170	
171	    for purpose in &purposes {
172	        if !purpose.attractor_id.is_empty() && !attractor_ids.contains(&purpose.attractor_id) {
173	            violations.push(LinkViolation {
174	                source: "purpose".to_string(),
175	                id: purpose.id.clone(),
176	                message: format!("missing attractor '{}'", purpose.attractor_id),
177	            });
178	        }
179	        if purpose.shortname.is_empty() {
180	            violations.push(LinkViolation {
181	                source: "purpose".to_string(),
182	                id: purpose.id.clone(),
183	                message: "missing shortname (use --shortname when adding)".to_string(),
184	            });
185	        }
186	    }
187	
188	    let forces = crate::storage::format::read_forces(&cfg.residual_dir)?;
189	    let residues = crate::storage::format::read_residues(&cfg.residual_dir)?;
190	    let registry = crate::structure::definition::components::load(&cfg.residual_dir)?;
191	    let mut force_ids = std::collections::HashSet::new();
192	    for s in &stressors {
193	        force_ids.insert(s.id.clone());
194	    }
195	    for p in &purposes {
196	        force_ids.insert(p.id.clone());
197	    }
198	    for f in &forces {
199	        force_ids.insert(f.id.clone());
200	    }
201	    let component_names: std::collections::HashSet<String> =
202	        registry.iter().map(|c| c.name.clone()).collect();
203	
204	    for force in &forces {
205	        if !force.attractor_id.is_empty() && !attractor_ids.contains(&force.attractor_id) {
206	            violations.push(LinkViolation {
207	                source: "force".to_string(),
208	                id: force.id.clone(),
209	                message: format!("missing attractor '{}'", force.attractor_id),
210	            });
211	        }
212	    }
213	
214	    for residue in &residues {
215	        if !residue.force_id.is_empty() && !force_ids.contains(&residue.force_id) {
216	            violations.push(LinkViolation {
217	                source: "residue".to_string(),
218	                id: residue.id.clone(),
219	                message: format!("force_id '{}' not found", residue.force_id),
220	            });
221	        }
222	        // whole-system-residue uses a virtual component outside the registry (A-07).
223	        if crate::structure::analysis::residues::is_whole_system_residue(residue) {
224	            continue;
225	        }
226	        if !residue.component_id.is_empty() && !component_names.contains(&residue.component_id) {
227	            violations.push(LinkViolation {
228	                source: "residue".to_string(),
229	                id: residue.id.clone(),
230	                message: format!(
231	                    "component_id '{}' not found in components.csv",
232	                    residue.component_id
233	                ),
234	            });
235	        }
236	    }
237	
238	    Ok(violations)
239	}
