241	pub fn parse_outcome(outcome_str: &str) -> Option<OutcomeParts> {
242	    let words: Vec<&str> = outcome_str.split_whitespace().collect();
243	    if words.len() < 3 {
244	        return None;
245	    }
246	    let subject = words[0].to_string();
247	    let verb = words[1].to_string();
248	    let predicate = words[2..].join(" ");
249	    Some(OutcomeParts {
250	        subject,
251	        verb,
252	        predicates: vec![predicate],
253	    })
254	}
