256	pub struct OutcomeParts {
257	    pub subject: String,
258	    pub verb: String,
259	    pub predicates: Vec<String>,
260	}
261	
262	pub struct OutcomeViolation {
263	    pub source: String,
264	    pub id: String,
265	    pub outcome_str: String,
266	    pub reason: String,
267	}
268	
269	pub struct LinkViolation {
270	    pub source: String,
271	    pub id: String,
272	    pub message: String,
273	}
