275	/// Check if any word or phrase in the outcome touches the terminology index.
276	pub fn outcome_uses_terminology(
277	    outcome_str: &str,
278	    parts: &OutcomeParts,
279	    index: &crate::storage::terminology::TermIndex,
280	) -> bool {
281	    if index.words.contains(&parts.subject.to_lowercase()) {
282	        return true;
283	    }
284	    if index.words.contains(&parts.verb.to_lowercase()) {
285	        return true;
286	    }
287	    for predicate in &parts.predicates {
288	        for word in predicate.split_whitespace() {
289	            if index.words.contains(&word.to_lowercase()) {
290	                return true;
291	            }
292	        }
293	    }
294	    let lower = outcome_str.to_lowercase();
295	    for phrase in &index.phrases {
296	        if phrase.len() >= 3 && lower.contains(phrase.as_str()) {
297	            return true;
298	        }
299	    }
300	    false
301	}
