241	/// Migrate a residual/ directory from naive on-disk shape to v3 artifacts.
242	pub fn migrate_residual_dir(residual_dir: &Path, force: bool) -> Result<MigrateReport> {
243	    if !residual_dir.is_dir() {
244	        bail!("residual dir not found: {}", residual_dir.display());
245	    }
246	
247	    let session = crate::storage::integrity::sessions::begin_mutation(residual_dir, force)?;
248	    let mut report = MigrateReport::default();
249	
250	    // --- config ---
251	    let config_path = residual_dir.join("config.toml");
252	    if config_path.exists() {
253	        let raw = fs::read_to_string(&config_path)?;
254	        if is_v3_config(&raw) && !force {
255	            // Already v3 config; leave as-is unless forcing a rewrite from naive isn't possible.
256	            report.config_migrated = false;
257	        } else if is_v3_config(&raw) {
258	            report.config_migrated = false;
259	        } else {
260	            let migrated = migrate_naive_to_v3(&raw)?;
261	            fs::write(&config_path, &migrated.toml)?;
262	            report.config_migrated = true;
263	        }
264	    } else {
265	        let cfg = StorageConfig::default();
266	        fs::write(&config_path, crate::storage::config::render_v3(&cfg))?;
267	        report.config_migrated = true;
268	    }
269	
270	    // --- terminology → lexicon ---
271	    let terms_naive = crate::storage::terminology::load(residual_dir)?;
272	    let term_names: Vec<String> = terms_naive.iter().map(|t| t.term.clone()).collect();
273	    let lexicon: Vec<LexiconTerm> = terms_naive
274	        .iter()
275	        .map(|t| LexiconTerm {
276	            term: t.term.clone(),
277	            definition: t.definition.clone(),
278	            domain: t.domain.clone(),
279	            aliases: t.related_terms.clone(),
280	        })
281	        .collect();
282	    format::write_lexicon(residual_dir, &lexicon)?;
283	    report.lexicon_terms = lexicon.len();
284	
285	    // --- stressors + purposes → forces + residues ---
286	    let stressors = crate::storage::stressors::load(residual_dir)?;
287	    let purposes = crate::storage::purposes::load(residual_dir)?;
288	    let mut forces = Vec::new();
289	    let mut residues = Vec::new();
290	    let mut residue_n: u32 = 0;
291	    let mut unmapped = Vec::new();
292	
293	    let mut push_components = |force_id: &str, field: &str| {
294	        for token in split_component_field(field) {
295	            let (component_id, notes) = match map_component_token(&token) {
296	                Some(mapped) => (mapped, format!("migrated from naive token '{token}'")),
297	                None => {
298	                    unmapped.push(token.clone());
299	                    (
300	                        token.clone(),
301	                        format!("migrated unmapped naive token '{token}'"),
302	                    )
303	                }
304	            };
305	            residue_n += 1;
306	            residues.push(Residue {
307	                id: format!("R-{residue_n:02}"),
308	                force_id: force_id.to_string(),
309	                component_id,
310	                status: "proposed".to_string(),
311	                notes,
312	            });
313	        }
314	    };
315	
316	    for s in &stressors {
317	        let outcomes = split_outcomes(&s.outcomes, &s.description);
318	        let shortname = shortname_for(
319	            &s.id,
320	            &[&s.outcomes, &s.description, &s.naive_change],
321	            &term_names,
322	        );
323	        forces.push(Force {
324	            id: s.id.clone(),
325	            kind: ForceKind::Stressor,
326	            shortname,
327	            naive_change: s.naive_change.clone(),
328	            outcomes,
329	            description: s.description.clone(),
330	            attractor_id: s.attractor_id.clone(),
331	        });
332	        push_components(&s.id, &s.components_affected);
333	    }
334	
335	    for p in &purposes {
336	        let outcomes = split_outcomes(&p.outcomes, &p.description);
337	        let shortname = shortname_for(
338	            &p.id,
339	            &[&p.outcomes, &p.description, &p.feature],
340	            &term_names,
341	        );
342	        forces.push(Force {
343	            id: p.id.clone(),
344	            kind: ForceKind::Purpose,
345	            shortname,
346	            naive_change: p.feature.clone(),
347	            outcomes,
348	            description: p.description.clone(),
349	            attractor_id: p.attractor_id.clone(),
350	        });
351	        push_components(&p.id, &p.components_enabled);
352	    }
353	
354	    format::write_forces(residual_dir, &forces)?;
355	    write_residues(residual_dir, &residues)?;
356	    report.forces = forces.len();
357	    report.residues = residues.len();
358	    unmapped.sort();
359	    unmapped.dedup();
360	    report.unmapped_components = unmapped;
361	
362	    // --- attractors valence → +/- states ---
363	    let attractors_path = residual_dir.join("attractors.csv");
364	    if attractors_path.exists() {
365	        let header = {
366	            let text = fs::read_to_string(&attractors_path)?;
367	            text.lines().next().unwrap_or("").to_string()
368	        };
369	        let v3_attractors = if header.contains("positive_state") {
370	            // Already v3 — re-load via format if present; else leave.
371	            format::read_attractors_v3(residual_dir)?
372	        } else {
373	            let naive_rows = load_naive_attractors(&attractors_path)?;
374	            naive_rows
375	                .into_iter()
376	                .map(|(id, name, valence, description, phase_state)| {
377	                    migrate_attractor_row(id, name, &valence, description, phase_state)
378	                })
379	                .collect()
380	        };
381	        write_attractors_v3(residual_dir, &v3_attractors)?;
382	        report.attractors = v3_attractors.len();
383	    }
384	
385	    session.commit()?;
386	    Ok(report)
387	}
