1	//! Commit message validation — lexicon/component vocabulary in git subjects.
2	//!
3	//! Body lines are never validated. Enforcement is opt-in via storage-config
4	//! (`commit_msg_enforce`); hook install warns by default.
5	
6	use anyhow::{bail, Context, Result};
7	use regex::Regex;
8	use std::collections::HashSet;
9	use std::path::Path;
10	
11	use crate::config::Config;
12	use crate::storage::config::StorageConfig;
13	use crate::storage::format;
14	use crate::storage::terminology;
15	use crate::structure::definition::components;
16	
17	const CONVENTIONAL_TYPES: &[&str] = &[
18	    "build", "chore", "ci", "docs", "feat", "fix", "perf", "refactor", "revert", "style", "test",
19	];
20	
21	const GENERAL_PREFIX: &str = "general - ";
22	
23	#[derive(Debug, Clone, PartialEq, Eq)]
24	pub enum CommitMsgVerdict {
25	    Ok,
26	    Warn(Vec<String>),
27	    Violation(Vec<String>),
28	}
29	
30	impl CommitMsgVerdict {
31	    pub fn messages(&self) -> &[String] {
32	        match self {
33	            Self::Ok => &[],
34	            Self::Warn(v) | Self::Violation(v) => v.as_slice(),
35	        }
36	    }
37	
38	    pub fn is_ok(&self) -> bool {
39	        matches!(self, Self::Ok)
40	    }
41	}
42	
43	#[derive(Debug, Clone)]
44	pub struct Vocabulary {
45	    phrases: Vec<String>,
46	    components: Vec<String>,
47	    force_ids: HashSet<String>,
48	}
49	
50	pub fn load_vocabulary(residual_dir: &Path) -> Result<Vocabulary> {
51	    let mut phrases = HashSet::new();
52	
53	    for term in format::read_lexicon(residual_dir)? {
54	        add_phrases(&mut phrases, &term.term);
55	        for alias in term.aliases.split('|') {
56	            add_phrases(&mut phrases, alias);
57	        }
58	    }
59	
60	    for term in terminology::load(residual_dir)? {
61	        add_phrases(&mut phrases, &term.term);
62	        for alias in term.related_terms.split('|') {
63	            add_phrases(&mut phrases, alias);
64	        }
65	    }
66	
67	    let mut phrase_vec: Vec<String> = phrases.into_iter().collect();
68	    phrase_vec.sort_by_key(|p| std::cmp::Reverse(p.len()));
69	
70	    let component_list = components::load(residual_dir)?
71	        .into_iter()
72	        .map(|c| c.name.to_lowercase())
73	        .collect::<Vec<_>>();
74	
75	    let force_ids = format::read_forces(residual_dir)?
76	        .into_iter()
77	        .map(|f| f.id)
78	        .collect();
79	
80	    Ok(Vocabulary {
81	        phrases: phrase_vec,
82	        components: component_list,
83	        force_ids,
84	    })
85	}
86	
87	fn add_phrases(set: &mut HashSet<String>, raw: &str) {
88	    let trimmed = raw.trim().to_lowercase();
89	    if trimmed.is_empty() {
90	        return;
91	    }
92	    set.insert(trimmed.clone());
93	    for token in trimmed.split_whitespace() {
94	        if token.len() >= 3 {
95	            set.insert(token.to_string());
96	        }
97	    }
98	}
99	
100	pub fn subject_line(message: &str) -> &str {
101	    message.lines().next().unwrap_or("").trim()
102	}
103	
104	pub fn check_subject(subject: &str, vocab: &Vocabulary, super_strict: bool) -> CommitMsgVerdict {
105	    let subject = subject.trim();
106	    if subject.is_empty() {
107	        return CommitMsgVerdict::Violation(vec!["commit subject is empty".into()]);
108	    }
109	
110	    let lower = subject.to_lowercase();
111	    let mut notes = Vec::new();
112	
113	    if let Some(kind) = conventional_prefix(&lower) {
114	        return CommitMsgVerdict::Violation(vec![format!(
115	            "conventional commit prefix '{kind}:' is not allowed — use a lexicon term, component name, or '{GENERAL_PREFIX}'"
116	        )]);
117	    }
118	
119	    if lower.starts_with(GENERAL_PREFIX) {
120	        return CommitMsgVerdict::Ok;
121	    }
122	
123	    if let Some((component, force_id, _summary)) = parse_force_subject(subject) {
124	        let mut problems = Vec::new();
125	        if !vocab.components.iter().any(|c| c == &component) {
126	            problems.push(format!("unknown component '{component}'"));
127	        }
128	        if !vocab.force_ids.contains(&force_id) {
129	            problems.push(format!("unknown force id '{force_id}'"));
130	        }
131	        if problems.is_empty() {
132	            return CommitMsgVerdict::Ok;
133	        }
134	        return CommitMsgVerdict::Violation(problems);
135	    }
136	
137	    if super_strict {
138	        return CommitMsgVerdict::Violation(vec![format!(
139	            "super_strict requires '<component>: S-<nn>: summary' or '<component>: P-<nn>: summary' or subject starting with '{GENERAL_PREFIX}'"
140	        )]);
141	    }
142	
143	    if text_uses_vocabulary(&lower, vocab) {
144	        return CommitMsgVerdict::Ok;
145	    }
146	
147	    notes.push(format!(
148	        "subject does not contain a lexicon term or component name — prefer '<component>: S-<nn>:' or start with '{GENERAL_PREFIX}'"
149	    ));
150	    CommitMsgVerdict::Violation(notes)
151	}
152	
153	fn conventional_prefix(lower_subject: &str) -> Option<&'static str> {
154	    for kind in CONVENTIONAL_TYPES {
155	        let bare = format!("{kind}:");
156	        if lower_subject.starts_with(&bare) {
157	            return Some(kind);
158	        }
159	        let scoped = format!("{kind}(");
160	        if lower_subject.starts_with(&scoped) && lower_subject.contains("):") {
161	            return Some(kind);
162	        }
163	    }
164	    None
165	}
166	
167	/// `<component>: S-12: summary` or `<component>: P-04: summary`
168	pub fn parse_force_subject(subject: &str) -> Option<(String, String, String)> {
169	    static RE: std::sync::OnceLock<Regex> = std::sync::OnceLock::new();
170	    let re = RE.get_or_init(|| {
171	        Regex::new(r"^([^:]+):\s*([SP]-\d+):\s*(.+)$").expect("force subject regex")
172	    });
173	    let caps = re.captures(subject.trim())?;
174	    Some((
175	        caps.get(1)?.as_str().trim().to_lowercase(),
176	        caps.get(2)?.as_str().to_uppercase(),
177	        caps.get(3)?.as_str().trim().to_string(),
178	    ))
179	}
180	
181	pub fn text_uses_vocabulary(lower_subject: &str, vocab: &Vocabulary) -> bool {
182	    for component in &vocab.components {
183	        if lower_subject.contains(component) {
184	            return true;
185	        }
186	    }
187	    for phrase in &vocab.phrases {
188	        if phrase.len() >= 3 && lower_subject.contains(phrase) {
189	            return true;
190	        }
191	    }
192	    false
193	}
194	
195	pub fn staged_component_hints(staged_paths: &[String], vocab: &Vocabulary) -> Vec<String> {
196	    let mut hits = HashSet::new();
197	    for path in staged_paths {
198	        let path_lower = path.to_lowercase();
199	        for component in &vocab.components {
200	            if path_lower.contains(component) {
201	                hits.insert(component.clone());
202	            }
203	        }
204	    }
205	    let mut out: Vec<String> = hits.into_iter().collect();
206	    out.sort();
207	    out
208	}
209	
210	pub fn suggest_subjects(
211	    cfg: &Config,
212	    staged_paths: &[String],
213	) -> Result<Vec<String>> {
214	    let vocab = load_vocabulary(&cfg.residual_dir)?;
215	    let hints = staged_component_hints(staged_paths, &vocab);
216	    let forces = format::read_forces(&cfg.residual_dir)?;
217	    let residues = format::read_residues(&cfg.residual_dir)?;
218	
219	    let mut suggestions = Vec::new();
220	
221	    for component in &hints {
222	        let mut added = false;
223	        for residue in residues
224	            .iter()
225	            .filter(|r| r.component_id.eq_ignore_ascii_case(component))
226	        {
227	            if let Some(force) = forces.iter().find(|f| f.id == residue.force_id) {
228	                let prefix = force.id.to_uppercase();
229	                let summary = force.shortname.replace('-', " ");
230	                suggestions.push(format!("{component}: {prefix}: {summary}"));
231	                added = true;
232	            }
233	        }
234	        if !added {
235	            suggestions.push(format!("{component}: short summary here"));
236	        }
237	    }
238	
239	    if suggestions.is_empty() && !hints.is_empty() {
240	        for component in hints {
241	            suggestions.push(format!("{component}: short summary here"));
242	        }
243	    }
244	
245	    if suggestions.is_empty() {
246	        suggestions.push(format!(
247	            "general - describe meta/tooling work, or use a lexicon term in the subject"
248	        ));
249	    }
250	
251	    Ok(suggestions)
252	}
253	
254	pub fn template_for_force(cfg: &Config, force_id: &str) -> Result<String> {
255	    let force_id = force_id.to_uppercase();
256	    let forces = format::read_forces(&cfg.residual_dir)?;
257	    let force = forces
258	        .iter()
259	        .find(|f| f.id.eq_ignore_ascii_case(&force_id))
260	        .with_context(|| format!("force '{force_id}' not found in forces.csv"))?;
261	
262	    let residues = format::read_residues(&cfg.residual_dir)?;
263	    let component = residues
264	        .iter()
265	        .find(|r| r.force_id.eq_ignore_ascii_case(&force.id))
266	        .map(|r| r.component_id.as_str())
267	        .unwrap_or("component-name");
268	
269	    let summary = force.shortname.replace('-', " ");
270	    Ok(format!(
271	        "{component}: {}: {summary}\n\n- \n- \n",
272	        force.id.to_uppercase()
273	    ))
274	}
