276	pub fn verify_message(
277	    cfg: &Config,
278	    policy: &StorageConfig,
279	    message: &str,
280	    staged_paths: &[String],
281	) -> Result<CommitMsgVerdict> {
282	    let subject = subject_line(message);
283	    let vocab = load_vocabulary(&cfg.residual_dir)?;
284	    let mut verdict = check_subject(subject, &vocab, policy.super_strict);
285	
286	    if !staged_paths.is_empty() {
287	        let hints = staged_component_hints(staged_paths, &vocab);
288	        if !hints.is_empty() && !verdict.is_ok() {
289	            if let CommitMsgVerdict::Violation(ref mut msgs) = verdict {
290	                msgs.push(format!(
291	                    "staged paths touch component(s): {} — consider a force-responsive subject",
292	                    hints.join(", ")
293	                ));
294	            }
295	        } else if !hints.is_empty() {
296	            let mentioned: HashSet<_> = hints
297	                .iter()
298	                .filter(|c| subject.to_lowercase().contains(c.as_str()))
299	                .cloned()
300	                .collect();
301	            if mentioned.is_empty() {
302	                let note = format!(
303	                    "staged paths touch {} but subject does not — optional hint",
304	                    hints.join(", ")
305	                );
306	                verdict = match verdict {
307	                    CommitMsgVerdict::Ok => CommitMsgVerdict::Warn(vec![note]),
308	                    CommitMsgVerdict::Warn(mut w) => {
309	                        w.push(note);
310	                        CommitMsgVerdict::Warn(w)
311	                    }
312	                    CommitMsgVerdict::Violation(mut v) => {
313	                        v.push(note);
314	                        CommitMsgVerdict::Violation(v)
315	                    }
316	                };
317	            }
318	        }
319	    }
320	
321	    Ok(verdict)
322	}
323	
324	pub fn run_verify(
325	    cfg: &Config,
326	    message: &str,
327	    staged_paths: &[String],
328	    enforce_override: Option<bool>,
329	) -> Result<()> {
330	    let policy = crate::verification::policy_from_storage_config(&cfg.residual_dir)?;
331	    let enforce = enforce_override.unwrap_or(policy.commit_msg_enforce);
332	    let verdict = verify_message(cfg, &policy, message, staged_paths)?;
333	
334	    match &verdict {
335	        CommitMsgVerdict::Ok => {
336	            println!("OK: commit subject uses project vocabulary.");
337	        }
338	        CommitMsgVerdict::Warn(msgs) => {
339	            for msg in msgs {
340	                println!("WARN: {msg}");
341	            }
342	            println!("OK (warn-only): commit-msg enforcement is disabled.");
343	        }
344	        CommitMsgVerdict::Violation(msgs) => {
345	            for msg in msgs {
346	                println!("VIOLATION: {msg}");
347	            }
348	            if enforce {
349	                bail!("commit message rejected (commit_msg_enforce = true)");
350	            }
351	            println!("WARN (enforce disabled): {} violation(s) — hook would allow this commit.", msgs.len());
352	        }
353	    }
354	    Ok(())
355	}
356	
357	pub fn git_staged_paths() -> Result<Vec<String>> {
358	    let out = std::process::Command::new("git")
359	        .args(["diff", "--cached", "--name-only"])
360	        .output()
361	        .context("run git diff --cached --name-only")?;
362	    if !out.status.success() {
363	        return Ok(vec![]);
364	    }
365	    Ok(String::from_utf8_lossy(&out.stdout)
366	        .lines()
367	        .map(|l| l.trim().to_string())
368	        .filter(|l| !l.is_empty())
369	        .collect())
370	}
