    fn alias_aware_lexicon_match() {
        let dir = tempdir().unwrap();
        seed_vocab(dir.path());
        let vocab = load_vocabulary(dir.path()).unwrap();
        assert!(check_subject(
            "expand residual-architecture notes",
            &vocab,
            false
