                r.status = "active".to_string();
                r
            }],
        )
        .unwrap();
        let cfg = cfg_for(dir.path());
        let tpl = template_for_force(&cfg, "S-28").unwrap();
        assert!(tpl.contains("verification-git-hook: S-28:"));
    }
}

