//! Force schema — 1/2 of a residue (the purpose/stressor inside it).
//!
//! A force carries naive_change + outcomes + shortname. It does **not** carry
//! traits or component lists; component mapping lives on Residue.

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ForceKind {
    Purpose,
    Stressor,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Force {
    pub id: String,
    pub kind: ForceKind,
    pub shortname: String,
    pub naive_change: String,
    pub outcomes: Vec<String>,
    pub description: String,
    pub attractor_id: String,
}

impl Force {
    pub fn purpose(
        id: impl Into<String>,
        shortname: impl Into<String>,
        naive_change: impl Into<String>,
        outcomes: Vec<String>,
    ) -> Self {
        Self {
            id: id.into(),
            kind: ForceKind::Purpose,
            shortname: shortname.into(),
            naive_change: naive_change.into(),
            outcomes,
            description: String::new(),
            attractor_id: String::new(),
        }
    }

    pub fn stressor(
        id: impl Into<String>,
        shortname: impl Into<String>,
        naive_change: impl Into<String>,
        outcomes: Vec<String>,
    ) -> Self {
        Self {
            id: id.into(),
            kind: ForceKind::Stressor,
            shortname: shortname.into(),
            naive_change: naive_change.into(),
            outcomes,
            description: String::new(),
            attractor_id: String::new(),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::structure::analysis::residues::Residue;

    #[test]
    fn force_is_half_of_residue() {
        let force = Force::purpose(
            "P-01",
            "auth-hub",
            "add auth without rewriting the hub",
            vec!["operator authenticates via residue mapping".into()],
        );
        let residue = Residue {
            id: "R-01".into(),
            force_id: force.id.clone(),
            component_id: "cli".into(),
            status: "proposed".into(),
            notes: String::new(),
        };
        assert_eq!(residue.force_id, force.id, "residue maps a force id");
        assert!(!residue.component_id.is_empty(), "residue maps a component id");
        assert_ne!(
            residue.force_id, residue.component_id,
            "force half and component half are distinct"
        );
        assert!(
            !force.outcomes.is_empty(),
            "force carries outcomes (the narrative half)"
        );
        let debug = format!("{:?}", force);
        assert!(
            !debug.to_lowercase().contains("trait"),
            "Force must not carry traits, got {debug}"
        );
        assert!(
            !debug.to_lowercase().contains("component"),
            "Force must not carry component lists, got {debug}"
        );
    }
}

//! Stressors schema — Force specialization (naive_change + outcomes, not traits).

use super::force::{Force, ForceKind};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Stressor {
    pub force: Force,
    /// Optional detection hook (S-14) — field on Force/Stressors, not a component.
    pub detection_mechanism: String,
}

impl Stressor {
    pub fn new(id: &str, shortname: &str, naive_change: &str, outcomes: Vec<String>) -> Self {
        Self {
            force: Force {
                id: id.to_string(),
                kind: ForceKind::Stressor,
                shortname: shortname.to_string(),
                naive_change: naive_change.to_string(),
                outcomes,
                description: String::new(),
                attractor_id: String::new(),
            },
            detection_mechanism: String::new(),
        }
    }

    pub fn as_force(&self) -> &Force {
        &self.force
    }
}

//! Purposes schema — Force specialization (naive_change + outcomes, not traits).

use super::force::{Force, ForceKind};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Purpose {
    pub force: Force,
    pub feature: String,
}

impl Purpose {
    pub fn new(id: &str, shortname: &str, naive_change: &str, outcomes: Vec<String>) -> Self {
        Self {
            force: Force {
                id: id.to_string(),
                kind: ForceKind::Purpose,
                shortname: shortname.to_string(),
                naive_change: naive_change.to_string(),
                outcomes,
                description: String::new(),
                attractor_id: String::new(),
            },
            feature: String::new(),
        }
    }

    pub fn as_force(&self) -> &Force {
        &self.force
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::structure::analysis::stressors::Stressor;

    #[test]
    fn purposes_and_stressors_carry_outcomes_not_traits() {
        let p = Purpose::new(
            "P-01",
            "add-purpose",
            "expose add-purpose without a session hub",
            vec!["operator records a purpose against an attractor".into()],
        );
        let s = Stressor::new(
            "S-01",
            "stub-skills",
            "stub skills so binary owns methodology",
            vec!["skill sessions follow binary methodology".into()],
        );
        assert!(!p.as_force().outcomes.is_empty(), "purposes must carry outcomes");
        assert!(!s.as_force().outcomes.is_empty(), "stressors must carry outcomes");
        assert!(matches!(p.as_force().kind, ForceKind::Purpose));
        assert!(matches!(s.as_force().kind, ForceKind::Stressor));
        for debug in [format!("{:?}", p), format!("{:?}", s)] {
            assert!(
                !debug.to_lowercase().contains("trait"),
                "forces must not carry traits, got {debug}"
            );
        }
    }
}

