fn outcome_uses_terminology_match() {
    let parts = OutcomeParts {
        subject: "system".to_string(),
        verb: "handles".to_string(),
        predicates: vec!["auth".to_string()],
    };
    let index = terminology::TermIndex {
        words: ["auth".to_string()].into_iter().collect(),
        phrases: vec![],
