97	pub fn check_subject(subject: &str, vocab: &Vocabulary, super_strict: bool) -> CommitMsgVerdict {
98	    let subject = subject.trim();
99	    if subject.is_empty() {
100	        return CommitMsgVerdict::Violation(vec!["commit subject is empty".into()]);
101	    }
102	
103	    let lower = subject.to_lowercase();
104	    let mut notes = Vec::new();
105	
106	    if let Some(kind) = conventional_prefix(&lower) {
107	        return CommitMsgVerdict::Violation(vec![format!(
108	            "conventional commit prefix '{kind}:' is not allowed — use a lexicon term, component name, or '{GENERAL_PREFIX}'"
109	        )]);
110	    }
111	
112	    if lower.starts_with(GENERAL_PREFIX) {
113	        return CommitMsgVerdict::Ok;
114	    }
115	
116	    if let Some((component, force_id, _summary)) = parse_force_subject(subject) {
117	        let mut problems = Vec::new();
118	        if !vocab.components.iter().any(|c| c == &component) {
119	            problems.push(format!("unknown component '{component}'"));
120	        }
121	        if !vocab.force_ids.contains(&force_id) {
122	            problems.push(format!("unknown force id '{force_id}'"));
123	        }
124	        if problems.is_empty() {
125	            return CommitMsgVerdict::Ok;
126	        }
127	        return CommitMsgVerdict::Violation(problems);
128	    }
129	
130	    if super_strict {
131	        return CommitMsgVerdict::Violation(vec![format!(
132	            "super_strict requires '<component>: S-<nn>: summary' or '<component>: P-<nn>: summary' or subject starting with '{GENERAL_PREFIX}'"
133	        )]);
134	    }
135	
136	    if text_uses_vocabulary(&lower, vocab) {
137	        return CommitMsgVerdict::Ok;
138	    }
139	
140	    notes.push(format!(
141	        "subject does not contain a lexicon term or component name — prefer '<component>: S-<nn>:' or start with '{GENERAL_PREFIX}'"
142	    ));
