146	fn conventional_prefix(lower_subject: &str) -> Option<&'static str> {
147	    for kind in CONVENTIONAL_TYPES {
148	        let bare = format!("{kind}:");
149	        if lower_subject.starts_with(&bare) {
150	            return Some(kind);
151	        }
152	        let scoped = format!("{kind}(");
153	        if lower_subject.starts_with(&scoped) && lower_subject.contains("):") {
154	            return Some(kind);
155	        }
156	    }
157	    None
158	}
