160	/// `<component>: S-12: summary` or `<component>: P-04: summary`
161	pub fn parse_force_subject(subject: &str) -> Option<(String, String, String)> {
162	    static RE: std::sync::OnceLock<Regex> = std::sync::OnceLock::new();
163	    let re = RE.get_or_init(|| {
164	        Regex::new(r"^([^:]+):\s*([SP]-\d+):\s*(.+)$").expect("force subject regex")
165	    });
166	    let caps = re.captures(subject.trim())?;
167	    Some((
168	        caps.get(1)?.as_str().trim().to_lowercase(),
169	        caps.get(2)?.as_str().to_uppercase(),
170	        caps.get(3)?.as_str().trim().to_string(),
171	    ))
172	}
