174	pub fn text_uses_vocabulary(lower_subject: &str, vocab: &Vocabulary) -> bool {
175	    for component in &vocab.components {
176	        if lower_subject.contains(component) {
177	            return true;
178	        }
179	    }
180	    for phrase in &vocab.phrases {
181	        if phrase.len() >= 3 && lower_subject.contains(phrase) {
182	            return true;
183	        }
184	    }
185	    false
186	}
