280	pub fn verify_message(
281	    cfg: &Config,
282	    policy: &StorageConfig,
283	    message: &str,
284	    staged_paths: &[String],
285	) -> Result<CommitMsgVerdict> {
286	    let subject = subject_line(message);
287	    let vocab = load_vocabulary(&cfg.residual_dir)?;
288	    let mut verdict = check_subject(subject, &vocab, policy.super_strict);
289	
290	    if !staged_paths.is_empty() {
291	        let hints = staged_component_hints(staged_paths, &vocab);
292	        if !hints.is_empty() && !verdict.is_ok() {
293	            if let CommitMsgVerdict::Violation(ref mut msgs) = verdict {
294	                msgs.push(format!(
295	                    "staged paths touch component(s): {} — consider a force-responsive subject",
296	                    hints.join(", ")
297	                ));
298	            }
299	        } else if !hints.is_empty() {
300	            let mentioned: HashSet<_> = hints
301	                .iter()
302	                .filter(|c| subject.to_lowercase().contains(c.as_str()))
303	                .cloned()
304	                .collect();
305	            if mentioned.is_empty() {
306	                let note = format!(
307	                    "staged paths touch {} but subject does not — optional hint",
308	                    hints.join(", ")
309	                );
310	                verdict = match verdict {
311	                    CommitMsgVerdict::Ok => CommitMsgVerdict::Warn(vec![note]),
312	                    CommitMsgVerdict::Warn(mut w) => {
313	                        w.push(note);
314	                        CommitMsgVerdict::Warn(w)
315	                    }
316	                    CommitMsgVerdict::Violation(mut v) => {
317	                        v.push(note);
318	                        CommitMsgVerdict::Violation(v)
319	                    }
320	                };
321	            }
322	        }
323	    }
324	
325	    Ok(verdict)
326	}
