328	pub fn run_verify(
329	    cfg: &Config,
330	    message: &str,
331	    staged_paths: &[String],
332	    enforce_override: Option<bool>,
333	) -> Result<()> {
334	    let policy = crate::verification::policy_from_storage_config(&cfg.residual_dir)?;
335	    let enforce = enforce_override.unwrap_or(policy.commit_msg_enforce);
336	    let verdict = verify_message(cfg, &policy, message, staged_paths)?;
337	
338	    match &verdict {
339	        CommitMsgVerdict::Ok => {
340	            println!("OK: commit subject uses project vocabulary.");
341	        }
342	        CommitMsgVerdict::Warn(msgs) => {
343	            for msg in msgs {
344	                println!("WARN: {msg}");
345	            }
346	            println!("OK (warn-only): commit-msg enforcement is disabled.");
347	        }
348	        CommitMsgVerdict::Violation(msgs) => {
349	            for msg in msgs {
350	                println!("VIOLATION: {msg}");
351	            }
352	            if enforce {
353	                bail!("commit message rejected (commit_msg_enforce = true)");
354	            }
355	            println!("WARN (enforce disabled): {} violation(s) — hook would allow this commit.", msgs.len());
356	        }
357	    }
358	    Ok(())
359	}
