361	pub fn git_staged_paths() -> Result<Vec<String>> {
362	    let out = std::process::Command::new("git")
363	        .args(["diff", "--cached", "--name-only"])
364	        .output()
365	        .context("run git diff --cached --name-only")?;
366	    if !out.status.success() {
367	        return Ok(vec![]);
368	    }
369	    Ok(String::from_utf8_lossy(&out.stdout)
370	        .lines()
371	        .map(|l| l.trim().to_string())
372	        .filter(|l| !l.is_empty())
373	        .collect())
374	}
