1	//! Format — current multi-file CSV; round-trip structure.analysis.* and
2	//! structure.definition.* ↔ CSV.
3	
4	use anyhow::Result;
5	use std::collections::{BTreeMap, BTreeSet};
6	use std::path::Path;
7	
8	use crate::structure::analysis::attractors::Attractor;
9	use crate::structure::analysis::residues::Residue;
10	use crate::structure::definition::lexicon::Term;
11	
12	const LEXICON_HEADER: &str = "term,definition,domain,aliases";
13	const RESIDUES_MATRIX_FORCE_COL: &str = "force";
14	const ATTRACTORS_V3_HEADER: &str = "id,name,description,positive_state,negative_state";
15	
16	pub fn write_lexicon(residual_dir: &Path, terms: &[Term]) -> Result<()> {
17	    let path = residual_dir.join("lexicon.csv");
18	    let mut buf = LEXICON_HEADER.to_string();
19	    buf.push('\n');
20	    for t in terms {
21	        let mut row = Vec::new();
22	        {
23	            let mut wtr = csv::WriterBuilder::new()
24	                .has_headers(false)
25	                .from_writer(&mut row);
26	            wtr.write_record(&[
27	                t.term.as_str(),
28	                t.definition.as_str(),
29	                t.domain.as_str(),
30	                t.aliases.as_str(),
31	            ])?;
32	            wtr.flush()?;
33	        }
34	        buf.push_str(std::str::from_utf8(&row)?);
35	    }
36	    std::fs::write(path, buf)?;
37	    Ok(())
38	}
39	
40	pub fn append_lexicon(residual_dir: &Path, term: Term) -> Result<()> {
41	    let mut terms = read_lexicon(residual_dir)?;
42	    terms.push(term);
43	    write_lexicon(residual_dir, &terms)
44	}
45	
46	pub fn read_lexicon(residual_dir: &Path) -> Result<Vec<Term>> {
47	    let path = residual_dir.join("lexicon.csv");
48	    if !path.exists() {
49	        return Ok(vec![]);
50	    }
51	    let mut rdr = csv::ReaderBuilder::new()
52	        .has_headers(true)
53	        .from_path(&path)?;
54	    let mut out = Vec::new();
55	    for rec in rdr.deserialize() {
56	        out.push(rec?);
57	    }
58	    Ok(out)
59	}
60	
61	fn parse_residue_cell(cell: &str) -> (String, String) {
62	    if let Some((status, notes)) = cell.split_once('|') {
63	        (status.trim().to_string(), notes.trim().to_string())
64	    } else {
65	        (cell.trim().to_string(), String::new())
66	    }
67	}
68	
69	fn format_residue_cell(status: &str, notes: &str) -> String {
70	    if notes.is_empty() {
71	        status.to_string()
72	    } else {
73	        format!("{status}|{notes}")
74	    }
75	}
76	
77	fn residues_is_matrix_header(header: &str) -> bool {
78	    header
79	        .split(',')
80	        .next()
81	        .map(|c| c.trim().eq_ignore_ascii_case(RESIDUES_MATRIX_FORCE_COL))
82	        .unwrap_or(false)
83	}
84	
85	fn residues_to_rows(
86	    residues: &[Residue],
87	) -> (
88	    Vec<String>,
89	    BTreeMap<String, BTreeMap<String, (String, String)>>,
90	) {
91	    let mut components = BTreeSet::new();
92	    let mut cells: BTreeMap<String, BTreeMap<String, (String, String)>> = BTreeMap::new();
93	    for r in residues {
94	        if r.force_id.is_empty() || r.component_id.is_empty() {
95	            continue;
96	        }
97	        components.insert(r.component_id.clone());
98	        cells
99	            .entry(r.force_id.clone())
100	            .or_default()
101	            .insert(r.component_id.clone(), (r.status.clone(), r.notes.clone()));
102	    }
103	    (components.into_iter().collect(), cells)
104	}
105	
106	fn render_residues_matrix(residues: &[Residue]) -> String {
107	    let (components, cells) = residues_to_rows(residues);
108	    let mut buf = RESIDUES_MATRIX_FORCE_COL.to_string();
109	    for c in &components {
110	        buf.push(',');
111	        buf.push_str(c);
112	    }
113	    buf.push('\n');
114	    for force_id in cells.keys() {
115	        let force_cells = cells
116	            .get(force_id)
117	            .expect("force_id comes from cells.keys()");
118	        let mut row = vec![force_id.as_str()];
119	        let mut cell_values = Vec::new();
120	        for c in &components {
121	            cell_values.push(
122	                force_cells
123	                    .get(c)
124	                    .map(|(s, n)| format_residue_cell(s, n))
125	                    .unwrap_or_default(),
126	            );
127	        }
128	        for v in &cell_values {
129	            row.push(v.as_str());
130	        }
131	        let mut out = Vec::new();
132	        {
133	            let mut wtr = csv::WriterBuilder::new()
134	                .has_headers(false)
135	                .from_writer(&mut out);
136	            wtr.write_record(&row)
137	                .expect("csv write to Vec<u8> is infallible");
138	            wtr.flush().expect("csv flush to Vec<u8> is infallible");
139	        }
140	        buf.push_str(
141	            std::str::from_utf8(&out).expect("csv output is always valid UTF-8"),
142	        );
143	    }
144	    buf
145	}
146	
147	pub fn format_residues_matrix(residual_dir: &Path) -> Result<String> {
148	    Ok(render_residues_matrix(&read_residues(residual_dir)?))
149	}
150	
151	pub fn write_residues(residual_dir: &Path, residues: &[Residue]) -> Result<()> {
152	    std::fs::write(
153	        residual_dir.join("residues.csv"),
154	        render_residues_matrix(residues),
155	    )?;
156	    Ok(())
157	}
158	
159	pub fn read_residues(residual_dir: &Path) -> Result<Vec<Residue>> {
